/// Read the probe's output into a verdict. Pure, so the interesting case is testable without a device.
///
/// A MISSING `rc=` line is a FAILURE, not a pass. That direction matters: the whole point of this
/// probe is to catch a binary that did not run, and defaulting an unparseable answer to "healthy"
/// would reinstate exactly the blind spot the pipeline bug created.
pub fn read_probe(out: &str) -> (bool, String) {
    let rc = out.lines().rev().find_map(|l| l.trim().strip_prefix("rc="));
    let body: Vec<&str> = out.lines().filter(|l| !l.trim().starts_with("rc=")).collect();
    let body = body.join(" ").trim().to_string();
    match rc {
        Some("0") => (true, body),
        Some(code) => (
            false,
            format!(
                "the binary exited {code}{}{}",
                if body.is_empty() { "" } else { " — " },
                body
            ),
        ),
        None => (false, format!("the probe returned no status — got: {}", out.trim())),
    }
}
